import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import {
  createBooking, approveBooking, rejectBooking, startBooking, completeBooking,
  replay, replayAll, DomainError,
} from '../src/domain/booking.ts';
import type { DomainEvent } from '../src/domain/events.ts';

process.env.GPU_BOOKING_NOW = '2026-08-04T00:00:00.000Z';

function requested(over: Partial<any> = {}): DomainEvent {
  return {
    type: 'BookingRequested',
    bookingId: 'bk-1',
    occurredAt: '2026-08-03T00:00:00.000Z',
    actorId: 'u-pat',
    userId: 'u-pat',
    userRole: 'STUDENT',
    resourceId: 'gpu-a100-01',
    startAt: '2026-08-05T09:00:00.000Z',
    endAt: '2026-08-05T13:00:00.000Z',
    requiresApproval: false,
    ...over,
  } as DomainEvent;
}

describe('การสร้างคำขอจอง', () => {
  const cmd = {
    bookingId: 'bk-new', userId: 'u-pat', userRole: 'STUDENT' as const,
    resourceId: 'gpu-a100-01',
    startAt: '2026-08-10T09:00:00.000Z', endAt: '2026-08-10T13:00:00.000Z',
  };

  test('REQ-07 คำขอใหม่มีสถานะ REQUESTED', () => {
    const state = replay(createBooking(cmd, []));
    assert.equal(state?.status, 'REQUESTED');
  });

  test('REQ-08 บันทึกเหตุการณ์ BookingRequested', () => {
    const events = createBooking(cmd, []);
    assert.equal(events[0].type, 'BookingRequested');
  });

  test('REQ-01 ขาดฟิลด์ที่จำเป็น -> 400', () => {
    assert.throws(
      () => createBooking({ ...cmd, resourceId: '' }, []),
      (e: DomainError) => e.httpStatus === 400,
    );
  });

  test('REQ-06 ไม่พบเครื่อง -> 404', () => {
    assert.throws(
      () => createBooking({ ...cmd, resourceId: 'gpu-h100-99' }, []),
      (e: DomainError) => e.httpStatus === 404,
    );
  });

  test('REQ-02 เวลาเริ่มอยู่ในอดีต -> 400', () => {
    assert.throws(
      () => createBooking({ ...cmd, startAt: '2026-01-01T09:00:00.000Z', endAt: '2026-01-01T13:00:00.000Z' }, []),
      (e: DomainError) => e.httpStatus === 400,
    );
  });

  test('REQ-03 endAt ไม่หลัง startAt -> 400', () => {
    assert.throws(
      () => createBooking({ ...cmd, endAt: cmd.startAt }, []),
      (e: DomainError) => e.httpStatus === 400,
    );
  });

  test('REQ-05 ช่วงเวลาซ้อนทับบนเครื่องเดียวกัน -> 409', () => {
    const existing = replayAll([requested({
      bookingId: 'bk-old',
      startAt: '2026-08-10T11:00:00.000Z', endAt: '2026-08-10T15:00:00.000Z',
    })]);
    assert.throws(() => createBooking(cmd, existing), (e: DomainError) => e.httpStatus === 409);
  });

  test('REQ-05 คนละเครื่อง ช่วงเวลาเดียวกัน จองได้', () => {
    const existing = replayAll([requested({
      bookingId: 'bk-old', resourceId: 'gpu-v100-01',
      startAt: '2026-08-10T11:00:00.000Z', endAt: '2026-08-10T15:00:00.000Z',
    })]);
    assert.equal(replay(createBooking(cmd, existing))?.status, 'REQUESTED');
  });

  test('REQ-17 จองเกิน 8 ชม. ถูกทำเครื่องหมายว่าต้องอนุมัติ', () => {
    const long = { ...cmd, endAt: '2026-08-10T20:00:00.000Z' };  // 11 ชม.
    assert.equal(replay(createBooking(long, []))?.requiresApproval, true);
  });

  test('REQ-23 จองไม่เกิน 8 ชม. ไม่ต้องอนุมัติ', () => {
    assert.equal(replay(createBooking(cmd, []))?.requiresApproval, false);
  });
});

describe('การอนุมัติ', () => {
  const state = replay([requested({ requiresApproval: true })])!;

  test('REQ-18 บทบาทอื่นอนุมัติไม่ได้ -> 403', () => {
    assert.throws(
      () => approveBooking(state, 'u-arun', 'LECTURER'),
      (e: DomainError) => e.httpStatus === 403,
    );
  });

  test('REQ-19 ผู้ขอจองอนุมัติของตัวเองไม่ได้ แม้เป็น LAB_ADMIN -> 403', () => {
    const own = replay([requested({ userId: 'u-admin', actorId: 'u-admin', requiresApproval: true })])!;
    assert.throws(
      () => approveBooking(own, 'u-admin', 'LAB_ADMIN'),
      (e: DomainError) => e.code === 'SELF_APPROVAL',
    );
  });

  test('REQ-20 อนุมัติได้เฉพาะสถานะ REQUESTED -> 409', () => {
    const rejected = replay([requested(), { type: 'BookingRejected', bookingId: 'bk-1', occurredAt: 'x', actorId: 'u-admin', reason: 'ไม่ว่าง' } as DomainEvent])!;
    assert.throws(
      () => approveBooking(rejected, 'u-admin', 'LAB_ADMIN'),
      (e: DomainError) => e.httpStatus === 409,
    );
  });

  test('อนุมัติสำเร็จ สถานะเปลี่ยนเป็น APPROVED และบันทึกผู้อนุมัติ', () => {
    const after = replay([requested({ requiresApproval: true }), ...approveBooking(state, 'u-admin', 'LAB_ADMIN')])!;
    assert.equal(after.status, 'APPROVED');
    assert.equal(after.approvedBy, 'u-admin');
  });

  test('REQ-21 ปฏิเสธโดยไม่ระบุเหตุผล -> 400', () => {
    assert.throws(
      () => rejectBooking(state, 'u-admin', 'LAB_ADMIN', '  '),
      (e: DomainError) => e.httpStatus === 400,
    );
  });
});

describe('การเริ่มและสิ้นสุดการใช้งาน', () => {
  test('REQ-17 การจองที่ต้องอนุมัติ เริ่มใช้งานก่อนได้รับอนุมัติไม่ได้ -> 409', () => {
    const state = replay([requested({ requiresApproval: true })])!;
    assert.throws(
      () => startBooking(state, 'u-pat'),
      (e: DomainError) => e.code === 'APPROVAL_REQUIRED',
    );
  });

  test('REQ-23 การจองที่ไม่ต้องอนุมัติ เริ่มใช้งานได้ทันที', () => {
    const state = replay([requested()])!;
    const after = replay([requested(), ...startBooking(state, 'u-pat')])!;
    assert.equal(after.status, 'ACTIVE');
  });

  test('REQ-31 สิ้นสุดการใช้งาน สถานะเป็น COMPLETED', () => {
    process.env.GPU_BOOKING_NOW = '2026-08-05T12:00:00.000Z';
    const evts = [requested()];
    const started = replay(evts)!;
    evts.push(...startBooking(started, 'u-pat'));
    const active = replay(evts)!;
    evts.push(...completeBooking(active, 'u-pat'));
    const done = replay(evts)!;
    assert.equal(done.status, 'COMPLETED');
    assert.equal(done.actualEndAt, '2026-08-05T12:00:00.000Z');
    process.env.GPU_BOOKING_NOW = '2026-08-04T00:00:00.000Z';
  });

  test('REQ-32 สิ้นสุดช้ากว่ากำหนดเกิน 15 นาที ระบบตัดจบที่ endAt + 15 นาที', () => {
    process.env.GPU_BOOKING_NOW = '2026-08-05T09:00:00.000Z';
    const evts = [requested()];
    evts.push(...startBooking(replay(evts)!, 'u-pat'));
    process.env.GPU_BOOKING_NOW = '2026-08-05T14:00:00.000Z';  // ช้ากว่า endAt 1 ชม.
    evts.push(...completeBooking(replay(evts)!, 'u-pat'));
    assert.equal(replay(evts)!.actualEndAt, '2026-08-05T13:15:00.000Z');
    process.env.GPU_BOOKING_NOW = '2026-08-04T00:00:00.000Z';
  });
});

describe('การเล่นเหตุการณ์ซ้ำ', () => {
  test('ไม่มีเหตุการณ์ -> ไม่มีสถานะ', () => {
    assert.equal(replay([]), null);
  });

  test('replayAll แยกตามรายการจองได้ถูกต้อง', () => {
    const all = replayAll([requested({ bookingId: 'a' }), requested({ bookingId: 'b' })]);
    assert.equal(all.length, 2);
    assert.deepEqual(all.map((s) => s.id).sort(), ['a', 'b']);
  });
});

/**
 * Aggregate ของการจอง
 *
 * รับคำสั่ง -> ตรวจกฎ -> คายเหตุการณ์ออกมา
 * ไม่มีการเก็บสถานะไว้ที่ไหน สถานะได้จากการเล่นเหตุการณ์ซ้ำเสมอ (replay)
 */

import type { BookingStatus, DomainEvent, Role } from './events.ts';
import { findResource, requiresApproval, OVERRUN_ALLOWANCE_MINUTES } from './policy.ts';
import { bookedHours } from '../lib/duration.ts';
import { nowIso } from '../lib/clock.ts';

export class DomainError extends Error {
  code: string;
  httpStatus: number;

  constructor(code: string, message: string, httpStatus: number) {
    super(message);
    this.name = 'DomainError';
    this.code = code;
    this.httpStatus = httpStatus;
  }
}

export interface BookingState {
  id: string;
  userId: string;
  userRole: Role;
  resourceId: string;
  startAt: string;
  endAt: string;
  status: BookingStatus;
  requiresApproval: boolean;
  approvedBy: string | null;
  rejectionReason: string | null;
  actualStartAt: string | null;
  actualEndAt: string | null;
}

/**
 * สร้างสถานะปัจจุบันจากเหตุการณ์ — หัวใจของ event sourcing
 * เหตุการณ์เดิม + ตรรกะที่เปลี่ยนไป = สถานะที่ต่างไป แม้ข้อมูลจะไม่ถูกแตะเลย
 */
export function replay(events: DomainEvent[]): BookingState | null {
  let s: BookingState | null = null;
  for (const e of events) {
    switch (e.type) {
      case 'BookingRequested':
        s = {
          id: e.bookingId, userId: e.userId, userRole: e.userRole, resourceId: e.resourceId,
          startAt: e.startAt, endAt: e.endAt, status: 'REQUESTED',
          requiresApproval: e.requiresApproval, approvedBy: null, rejectionReason: null,
          actualStartAt: null, actualEndAt: null,
        };
        break;
      case 'BookingApproved':
        if (s) { s.status = 'APPROVED'; s.approvedBy = e.actorId; }
        break;
      case 'BookingRejected':
        if (s) { s.status = 'REJECTED'; s.rejectionReason = e.reason; }
        break;
      case 'BookingStarted':
        if (s) { s.status = 'ACTIVE'; s.actualStartAt = e.actualStartAt; }
        break;
      case 'BookingCompleted':
        if (s) { s.status = 'COMPLETED'; s.actualEndAt = e.actualEndAt; }
        break;
    }
  }
  return s;
}

/** จัดกลุ่มเหตุการณ์ตามรายการจอง แล้ว replay ทีละรายการ */
export function replayAll(events: DomainEvent[]): BookingState[] {
  const byId = new Map<string, DomainEvent[]>();
  for (const e of events) {
    if (!byId.has(e.bookingId)) byId.set(e.bookingId, []);
    byId.get(e.bookingId)!.push(e);
  }
  return [...byId.values()].map(replay).filter((s): s is BookingState => s !== null);
}

/** สถานะที่ยังจับจองทรัพยากรอยู่ ใช้ตรวจการซ้อนทับ (REQ-05) */
const OCCUPYING: BookingStatus[] = ['REQUESTED', 'APPROVED', 'ACTIVE'];

function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string): boolean {
  return new Date(aStart) < new Date(bEnd) && new Date(bStart) < new Date(aEnd);
}

export interface CreateBookingCommand {
  bookingId: string;
  userId: string;
  userRole: Role;
  resourceId: string;
  startAt: string;
  endAt: string;
}

/**
 * สร้างคำขอจอง
 *
 * บังคับใช้แล้ว: REQ-01, REQ-02, REQ-03, REQ-05, REQ-06, REQ-07, REQ-08, REQ-17
 */
export function createBooking(cmd: CreateBookingCommand, existing: BookingState[]): DomainEvent[] {
  if (!cmd.resourceId || !cmd.startAt || !cmd.endAt) {
    throw new DomainError('MISSING_FIELD', 'ต้องระบุ resourceId, startAt และ endAt', 400);
  }
  if (!findResource(cmd.resourceId)) {
    throw new DomainError('RESOURCE_NOT_FOUND', `ไม่พบเครื่อง ${cmd.resourceId}`, 404);
  }
  const now = new Date(nowIso());
  if (new Date(cmd.startAt) <= now) {
    throw new DomainError('START_IN_PAST', 'startAt ต้องเป็นเวลาในอนาคต', 400);
  }
  if (new Date(cmd.endAt) <= new Date(cmd.startAt)) {
    throw new DomainError('INVALID_RANGE', 'endAt ต้องอยู่หลัง startAt', 400);
  }

  const clash = existing.find(
    (b) => b.resourceId === cmd.resourceId && OCCUPYING.includes(b.status) &&
           overlaps(cmd.startAt, cmd.endAt, b.startAt, b.endAt),
  );
  if (clash) {
    throw new DomainError('OVERLAPPING_BOOKING', `ช่วงเวลาซ้อนทับกับการจอง ${clash.id}`, 409);
  }

  return [{
    type: 'BookingRequested',
    bookingId: cmd.bookingId,
    occurredAt: nowIso(),
    actorId: cmd.userId,
    userId: cmd.userId,
    userRole: cmd.userRole,
    resourceId: cmd.resourceId,
    startAt: cmd.startAt,
    endAt: cmd.endAt,
    requiresApproval: requiresApproval(bookedHours(cmd.startAt, cmd.endAt)),
  }];
}

/** อนุมัติคำขอ — REQ-18, REQ-19, REQ-20 */
export function approveBooking(state: BookingState, approverId: string, approverRole: Role): DomainEvent[] {
  if (approverRole !== 'LAB_ADMIN') {
    throw new DomainError('FORBIDDEN', 'ผู้อนุมัติต้องมีบทบาท LAB_ADMIN', 403);
  }
  if (approverId === state.userId) {
    throw new DomainError('SELF_APPROVAL', 'ผู้ขอจองอนุมัติคำขอของตัวเองไม่ได้', 403);
  }
  if (state.status !== 'REQUESTED') {
    throw new DomainError('INVALID_STATE', `อนุมัติไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  return [{ type: 'BookingApproved', bookingId: state.id, occurredAt: nowIso(), actorId: approverId }];
}

/** ปฏิเสธคำขอ — REQ-18, REQ-21 */
export function rejectBooking(state: BookingState, actorId: string, actorRole: Role, reason: string): DomainEvent[] {
  if (actorRole !== 'LAB_ADMIN') {
    throw new DomainError('FORBIDDEN', 'ผู้ปฏิเสธต้องมีบทบาท LAB_ADMIN', 403);
  }
  if (!reason || !reason.trim()) {
    throw new DomainError('MISSING_REASON', 'การปฏิเสธต้องระบุเหตุผล', 400);
  }
  if (state.status !== 'REQUESTED') {
    throw new DomainError('INVALID_STATE', `ปฏิเสธไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  return [{ type: 'BookingRejected', bookingId: state.id, occurredAt: nowIso(), actorId, reason }];
}

/** เริ่มใช้งานจริง — REQ-23, REQ-29 (การจองเกินเกณฑ์ต้องผ่านการอนุมัติก่อน ตาม REQ-17) */
export function startBooking(state: BookingState, actorId: string): DomainEvent[] {
  if (state.requiresApproval && state.status !== 'APPROVED') {
    throw new DomainError('APPROVAL_REQUIRED', 'การจองนี้ต้องได้รับอนุมัติก่อนเริ่มใช้งาน', 409);
  }
  if (!state.requiresApproval && !['REQUESTED', 'APPROVED'].includes(state.status)) {
    throw new DomainError('INVALID_STATE', `เริ่มใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  if (state.status === 'ACTIVE') {
    throw new DomainError('INVALID_STATE', 'เริ่มใช้งานไปแล้ว', 409);
  }
  return [{ type: 'BookingStarted', bookingId: state.id, occurredAt: nowIso(), actorId, actualStartAt: nowIso() }];
}

/** สิ้นสุดการใช้งาน — REQ-31, REQ-32 */
export function completeBooking(state: BookingState, actorId: string): DomainEvent[] {
  if (state.status !== 'ACTIVE') {
    throw new DomainError('INVALID_STATE', `สิ้นสุดการใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  const limit = new Date(new Date(state.endAt).getTime() + OVERRUN_ALLOWANCE_MINUTES * 60000);
  const actual = new Date(nowIso());
  const actualEndAt = (actual > limit ? limit : actual).toISOString();
  return [{ type: 'BookingCompleted', bookingId: state.id, occurredAt: nowIso(), actorId, actualEndAt }];
}

/**
 * Aggregate ของการจอง
 *
 * รับคำสั่ง -> ตรวจกฎ -> คายเหตุการณ์ออกมา
 * ไม่มีการเก็บสถานะไว้ที่ไหน สถานะได้จากการเล่นเหตุการณ์ซ้ำเสมอ (replay)
 */

import type { BookingStatus, DomainEvent, Role } from './events.ts';
import { findResource, requiresApproval, MAX_HOURS_PER_BOOKING, OVERRUN_ALLOWANCE_MINUTES } from './policy.ts';
import { bookedHours } from '../lib/duration.ts';
import { nowIso } from '../lib/clock.ts';

export class DomainError extends Error {
  code: string;
  httpStatus: number;

  constructor(code: string, message: string, httpStatus: number) {
    super(message);
    this.name = 'DomainError';
    this.code = code;
    this.httpStatus = httpStatus;
  }
}

export interface BookingState {
  id: string;
  userId: string;
  userRole: Role;
  resourceId: string;
  startAt: string;
  endAt: string;
  status: BookingStatus;
  requiresApproval: boolean;
  approvedBy: string | null;
  rejectionReason: string | null;
  actualStartAt: string | null;
  actualEndAt: string | null;
}

/**
 * สร้างสถานะปัจจุบันจากเหตุการณ์ — หัวใจของ event sourcing
 * เหตุการณ์เดิม + ตรรกะที่เปลี่ยนไป = สถานะที่ต่างไป แม้ข้อมูลจะไม่ถูกแตะเลย
 */
export function replay(events: DomainEvent[]): BookingState | null {
  let s: BookingState | null = null;
  for (const e of events) {
    switch (e.type) {
      case 'BookingRequested':
        s = {
          id: e.bookingId, userId: e.userId, userRole: e.userRole, resourceId: e.resourceId,
          startAt: e.startAt, endAt: e.endAt, status: 'REQUESTED',
          requiresApproval: e.requiresApproval, approvedBy: null, rejectionReason: null,
          actualStartAt: null, actualEndAt: null,
        };
        break;
      case 'BookingApproved':
        if (s) { s.status = 'APPROVED'; s.approvedBy = e.actorId; }
        break;
      case 'BookingRejected':
        if (s) { s.status = 'REJECTED'; s.rejectionReason = e.reason; }
        break;
      case 'BookingStarted':
        if (s) { s.status = 'ACTIVE'; s.actualStartAt = e.actualStartAt; }
        break;
      case 'BookingCompleted':
        if (s) { s.status = 'COMPLETED'; s.actualEndAt = e.actualEndAt; }
        break;
    }
  }
  return s;
}

/** จัดกลุ่มเหตุการณ์ตามรายการจอง แล้ว replay ทีละรายการ */
export function replayAll(events: DomainEvent[]): BookingState[] {
  const byId = new Map<string, DomainEvent[]>();
  for (const e of events) {
    if (!byId.has(e.bookingId)) byId.set(e.bookingId, []);
    byId.get(e.bookingId)!.push(e);
  }
  return [...byId.values()].map(replay).filter((s): s is BookingState => s !== null);
}

/** สถานะที่ยังจับจองทรัพยากรอยู่ ใช้ตรวจการซ้อนทับ (REQ-05) */
const OCCUPYING: BookingStatus[] = ['REQUESTED', 'APPROVED', 'ACTIVE'];

function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string): boolean {
  return new Date(aStart) < new Date(bEnd) && new Date(bStart) < new Date(aEnd);
}

export interface CreateBookingCommand {
  bookingId: string;
  userId: string;
  userRole: Role;
  resourceId: string;
  startAt: string;
  endAt: string;
}

/**
 * สร้างคำขอจอง
 *
 * บังคับใช้แล้ว: REQ-01, REQ-02, REQ-03, REQ-05, REQ-06, REQ-07, REQ-08, REQ-17
 */
export function createBooking(cmd: CreateBookingCommand, existing: BookingState[]): DomainEvent[] {
  if (!cmd.resourceId || !cmd.startAt || !cmd.endAt) {
    throw new DomainError('MISSING_FIELD', 'ต้องระบุ resourceId, startAt และ endAt', 400);
  }
  if (!findResource(cmd.resourceId)) {
    throw new DomainError('RESOURCE_NOT_FOUND', `ไม่พบเครื่อง ${cmd.resourceId}`, 404);
  }
  const now = new Date(nowIso());
  if (new Date(cmd.startAt) <= now) {
    throw new DomainError('START_IN_PAST', 'startAt ต้องเป็นเวลาในอนาคต', 400);
  }
  if (new Date(cmd.endAt) <= new Date(cmd.startAt)) {
    throw new DomainError('INVALID_RANGE', 'endAt ต้องอยู่หลัง startAt', 400);
  }

  const clash = existing.find(
    (b) => b.resourceId === cmd.resourceId && OCCUPYING.includes(b.status) &&
           overlaps(cmd.startAt, cmd.endAt, b.startAt, b.endAt),
  );
  if (clash) {
    throw new DomainError('OVERLAPPING_BOOKING', `ช่วงเวลาซ้อนทับกับการจอง ${clash.id}`, 409);
  }

  return [{
    type: 'BookingRequested',
    bookingId: cmd.bookingId,
    occurredAt: nowIso(),
    actorId: cmd.userId,
    userId: cmd.userId,
    userRole: cmd.userRole,
    resourceId: cmd.resourceId,
    startAt: cmd.startAt,
    endAt: cmd.endAt,
    requiresApproval: requiresApproval(bookedHours(cmd.startAt, cmd.endAt)),
  }];
}

/** อนุมัติคำขอ — REQ-18, REQ-19, REQ-20 */
export function approveBooking(state: BookingState, approverId: string, approverRole: Role): DomainEvent[] {
  if (approverRole !== 'LAB_ADMIN') {
    throw new DomainError('FORBIDDEN', 'ผู้อนุมัติต้องมีบทบาท LAB_ADMIN', 403);
  }
  if (approverId === state.userId) {
    throw new DomainError('SELF_APPROVAL', 'ผู้ขอจองอนุมัติคำขอของตัวเองไม่ได้', 403);
  }
  if (state.status !== 'REQUESTED') {
    throw new DomainError('INVALID_STATE', `อนุมัติไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  return [{ type: 'BookingApproved', bookingId: state.id, occurredAt: nowIso(), actorId: approverId }];
}

/** ปฏิเสธคำขอ — REQ-18, REQ-21 */
export function rejectBooking(state: BookingState, actorId: string, actorRole: Role, reason: string): DomainEvent[] {
  if (actorRole !== 'LAB_ADMIN') {
    throw new DomainError('FORBIDDEN', 'ผู้ปฏิเสธต้องมีบทบาท LAB_ADMIN', 403);
  }
  if (!reason || !reason.trim()) {
    throw new DomainError('MISSING_REASON', 'การปฏิเสธต้องระบุเหตุผล', 400);
  }
  if (state.status !== 'REQUESTED') {
    throw new DomainError('INVALID_STATE', `ปฏิเสธไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  return [{ type: 'BookingRejected', bookingId: state.id, occurredAt: nowIso(), actorId, reason }];
}

/** เริ่มใช้งานจริง — REQ-23, REQ-29 (การจองเกินเกณฑ์ต้องผ่านการอนุมัติก่อน ตาม REQ-17) */
export function startBooking(state: BookingState, actorId: string): DomainEvent[] {
  if (state.requiresApproval && state.status !== 'APPROVED') {
    throw new DomainError('APPROVAL_REQUIRED', 'การจองนี้ต้องได้รับอนุมัติก่อนเริ่มใช้งาน', 409);
  }
  if (!state.requiresApproval && !['REQUESTED', 'APPROVED'].includes(state.status)) {
    throw new DomainError('INVALID_STATE', `เริ่มใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  if (state.status === 'ACTIVE') {
    throw new DomainError('INVALID_STATE', 'เริ่มใช้งานไปแล้ว', 409);
  }
  return [{ type: 'BookingStarted', bookingId: state.id, occurredAt: nowIso(), actorId, actualStartAt: nowIso() }];
}

/** สิ้นสุดการใช้งาน — REQ-31, REQ-32 */
export function completeBooking(state: BookingState, actorId: string): DomainEvent[] {
  if (state.status !== 'ACTIVE') {
    throw new DomainError('INVALID_STATE', `สิ้นสุดการใช้งานไม่ได้เมื่อสถานะเป็น ${state.status}`, 409);
  }
  const limit = new Date(new Date(state.endAt).getTime() + OVERRUN_ALLOWANCE_MINUTES * 60000);
  const actual = new Date(nowIso());
  const actualEndAt = (actual > limit ? limit : actual).toISOString();
  return [{ type: 'BookingCompleted', bookingId: state.id, occurredAt: nowIso(), actorId, actualEndAt }];
}

