/** สัดส่วนที่คิดค่าบริการเมื่อจองแล้วไม่มาใช้ (REQ-36) */
export const NO_SHOW_CHARGE_RATIO = 0.5;

/** ไม่มาใช้ภายในกี่นาทีหลังเวลาเริ่ม ถือเป็นไม่มาใช้ (REQ-30) */
